const THRESHOLD = 0.83; // cosine similarity ≥ this = treat as duplicate (tuned 2026-08-24: real reworded-story pair measured 0.85, unrelated stories measured ~0.35-0.38)

function cosineSim(a, b) {
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    na += a[i] * a[i];
    nb += b[i] * b[i];
  }
  return dot / (Math.sqrt(na) * Math.sqrt(nb) + 1e-9);
}

const embedded = $input.all();
const kept = [];
const keptVectors = [];
let droppedCount = 0;
const droppedTitles = [];

for (let i = 0; i < embedded.length; i++) {
  const vec = embedded[i].json.embedding;
  const original = $("Parse & Validate Enrichment").itemMatching(i).json;

  if (!Array.isArray(vec) || vec.length === 0) {
    // no embedding (e.g. Ollama call failed for this item) -- keep it rather than silently drop
    keptVectors.push(null);
    kept.push({ json: original });
    continue;
  }

  let isDup = false;
  for (const kv of keptVectors) {
    if (kv && cosineSim(vec, kv) >= THRESHOLD) { isDup = true; break; }
  }

  if (isDup) {
    droppedCount++;
    droppedTitles.push(original.title);
    continue;
  }

  keptVectors.push(vec);
  kept.push({ json: original });
}

if (droppedCount > 0) {
  console.log(`Dedup: dropped ${droppedCount} near-duplicate article(s): ${droppedTitles.join(" | ")}`);
}

return kept;

