// Round-robin across sites: Solr returns the newest ~200 articles, but the crawler
// ingests feed-by-feed, so "newest 25" was often 25 items from whichever single
// site was crawled last. Take each site's newest first, then second-newest, etc.
const MAX_ITEMS = 25;
const docs = $input.first().json.response.docs;
const hostOf = (u) => { try { return new URL(u).hostname.replace(/^www\./, ''); } catch (e) { return 'unknown'; } };
const groups = new Map();
for (const doc of docs) {
  const h = hostOf(doc.id);
  if (!groups.has(h)) groups.set(h, []);
  groups.get(h).push(doc);
}
const picked = [];
for (let i = 0; picked.length < MAX_ITEMS; i++) {
  let any = false;
  for (const list of groups.values()) {
    if (i < list.length && picked.length < MAX_ITEMS) { picked.push(list[i]); any = true; }
  }
  if (!any) break;
}
const items = [];
for (const doc of picked) {
  const title = Array.isArray(doc.title_txt) ? doc.title_txt[0] : (doc.title_txt || doc.id);
  const content = (doc.content_txt && doc.content_txt[0]) ? doc.content_txt[0].replace(/\s+/g, ' ').trim().slice(0, 6000) : '';
  let source = (doc.og_site_name_ss && doc.og_site_name_ss[0]) || (doc.dc_publisher_ss && doc.dc_publisher_ss[0]) || hostOf(doc.id);
  items.push({ json: { url: doc.id, title: title, content: content, source: source, published_at: doc.file_modified_dt } });
}
return items;

const VALID_CATEGORIES = ['technology','market','health','science','business','trending','general'];
const items = $('Parse & Validate Enrichment').all();
const byCategory = {};
for (const it of items) {
  const cat = it.json.category;
  if (!byCategory[cat]) byCategory[cat] = [];
  byCategory[cat].push(it.json);
}
const out = [];
for (const cat of VALID_CATEGORIES) {
  const arts = byCategory[cat];
  if (!arts || arts.length === 0) continue;
  const lines = arts
    .sort((a,b) => b.importance_score - a.importance_score)
    .slice(0, 8)
    .map(a => `• ${a.title} (${a.source})\n  ${a.summary}\n  ${a.url}`);
  const body = `📰 ${cat.toUpperCase()} — ${arts.length} article${arts.length>1?'s':''}\n\n` + lines.join('\n\n');
  out.push({ json: { category: cat, count: arts.length, body: body } });
}
return out;

const VALID_CATEGORIES = ['technology','market','health','science','business','trending','general'];
const enrichItems = $input.all();
const sourceItems = $('Extract Articles').all();
const out = [];
for (let i = 0; i < enrichItems.length; i++) {
  const raw = enrichItems[i].json.response || '';
  const src = sourceItems[i].json;
  let parsed = {};
  try {
    const match = raw.match(/\{[\s\S]*\}/);
    parsed = JSON.parse(match ? match[0] : raw);
  } catch (e) { parsed = {}; }
  const category = VALID_CATEGORIES.includes(String(parsed.category || '').toLowerCase())
    ? String(parsed.category).toLowerCase() : 'general';
  const importance = Number(parsed.importance_score);
  out.push({ json: {
    url: src.url, title: src.title, source: src.source, published_at: src.published_at,
    summary: parsed.summary || src.title, category: category,
    sentiment: ['positive','negative','neutral','mixed'].includes(String(parsed.sentiment||'').toLowerCase())
      ? String(parsed.sentiment).toLowerCase() : 'neutral',
    importance_score: isNaN(importance) ? 0.5 : Math.max(0, Math.min(1, importance))
  }});
}
return out;
